begin;
do $$declare a uuid;c uuid:=gen_random_uuid();p uuid:=gen_random_uuid();m uuid:=gen_random_uuid();u uuid:=gen_random_uuid();g uuid:=gen_random_uuid();l uuid:=gen_random_uuid();f uuid:=gen_random_uuid();s uuid:=gen_random_uuid();d jsonb:='{"title":"QA fulfilment request","proposed_scope":"QA approved scope","justification":"QA need","cost_impact":"QA recorded assessment","schedule_impact":"QA recorded timing","evidence":"QA decision reference","status":"Draft","decision_note":""}';begin
 select id into a from public.profiles where active and role='admin' order by id limit 1;
 if a is null then raise exception 'Administrator test prerequisite missing';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 insert into public.companies(id,name) values(c,'QA fulfilment rollback company');
 insert into public.projects(id,company_id,title) values(p,c,'QA fulfilment rollback project');
 insert into auth.users(id) values(m),(u);
 insert into public.profiles(id,name,role,company_id) values(m,'QA fulfilment rollback manager','team',null),(u,'QA fulfilment rollback client','client',c);
 insert into public.crm_teams(id,name) values(g,'QA fulfilment rollback team');
 insert into public.crm_memberships(user_id,role_id,team_id) values(m,'project_manager',g);
 insert into public.project_assignments(project_id,technician_id) values(p,m);
 perform set_config('request.jwt.claim.sub',m::text,true);execute 'set local role authenticated';
 perform public.save_project_change(l,null,p,d,'QA draft');
 perform public.save_project_change(l,1,p,d||'{"status":"Submitted"}','QA submit');
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.save_project_change(l,2,p,d||'{"status":"Approved","decision_note":"QA internal decision"}','QA approve');
 perform public.record_change_fulfilment(f,l,3,null,'Partially fulfilled','QA scope coverage','QA remaining work','QA evidence','QA reason');
 if not exists(select 1 from public.crm_change_fulfilment where id=f and actor_id=a and revision=1 and status='Partially fulfilled') then raise exception 'assessment attribution';end if;
 perform public.record_change_fulfilment(f,l,3,null,'Partially fulfilled','QA scope coverage','QA remaining work','QA evidence','QA reason');
 if (select count(*) from public.crm_change_fulfilment where change_id=l)<>1 then raise exception 'duplicate retry';end if;
 if not exists(select 1 from public.crm_change_fulfilment where id=f and decision_snapshot->'details'->>'proposed_scope'='QA approved scope' and application_snapshot='[]') then raise exception 'frozen scope';end if;
 begin perform public.record_change_fulfilment(s,l,3,null,'Fulfilled','QA coverage','QA none','QA evidence','QA reason');raise exception 'allowed';exception when others then if sqlerrm<>'Current prior assessment required; refresh before recording' then raise;end if;end;
 begin perform public.record_change_fulfilment(s,l,3,f,'Fulfilled','QA coverage',' ','QA evidence','QA reason');raise exception 'allowed';exception when others then if sqlerrm<>'Bounded status, coverage, remaining work, evidence and reason required' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',m::text,true);
 begin perform public.record_change_fulfilment(s,l,3,f,'Fulfilled','QA coverage','QA none','QA evidence','QA reason');raise exception 'allowed';exception when others then if sqlerrm<>'Active administrator required' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.record_change_fulfilment(s,l,3,f,'Fulfilled','QA scope coverage','QA explicitly none','QA reviewed evidence','QA correction reason');
 if not exists(select 1 from public.crm_change_fulfilment where id=s and revision=2 and previous_id=f) then raise exception 'correction linkage';end if;
 if not exists(select 1 from public.crm_change_fulfilment where id=f and status='Partially fulfilled' and reason='QA reason') then raise exception 'prior changed';end if;
 begin update public.crm_change_fulfilment set status='Not fulfilled' where id=s;raise exception 'allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',u::text,true);
 if exists(select 1 from public.crm_change_fulfilment where change_id=l) then raise exception 'client visibility';end if;
 begin perform public.record_change_fulfilment(s,l,3,f,'Fulfilled','QA scope coverage','QA explicitly none','QA reviewed evidence','QA correction reason');raise exception 'allowed';exception when others then if sqlerrm<>'Active administrator required' then raise;end if;end;
 if has_function_privilege('anon','public.record_change_fulfilment(uuid,uuid,integer,uuid,text,text,text,text,text)','execute') then raise exception 'anonymous access';end if;
end$$;
select true as passed,12 as assertions,true as fixtures_rollback;
